import type { SessionConfig } from "../src/utils/session.ts";
import { beforeEach, describe, vi } from "vitest";
import {
  useSession,
  getSession,
  updateSession,
  clearSession,
  sealSession,
  unsealSession,
  readBody,
  H3,
  HTTPError,
} from "../src/index.ts";
import { seal, unseal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("session", (t, { it, expect }) => {
  let app: H3;

  let cookie = "";

  let sessionIdCtr = 0;
  const sessionConfig: SessionConfig = {
    name: "h3-test",
    password: "1234567123456712345671234567123456712345671234567",
    generateId: () => ++sessionIdCtr + "",
  };

  beforeEach(() => {
    app = new H3({});
    t.app.all("/", async (event) => {
      const session = await useSession(event, sessionConfig);
      if (event.req.method === "POST") {
        await session.update((await readBody(event)) as any);
      }
      return { session };
    });
    t.app.use(app.handler);
  });

  it("initiates session", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()).toHaveLength(1);
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("sets SameSite=Lax by default", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()[0]).toContain("SameSite=Lax");
  });

  it("allows overriding SameSite via config.cookie", async () => {
    t.app.get("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: "strict" },
      });
      return { session };
    });
    const strict = await t.fetch("/strict");
    expect(strict.headers.getSetCookie()[0]).toContain("SameSite=Strict");

    t.app.get("/none", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: false },
      });
      return { session };
    });
    const none = await t.fetch("/none");
    expect(none.headers.getSetCookie()[0]).not.toContain("SameSite");
  });

  it("gets same session back", async () => {
    const result = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("set session data", async () => {
    const result = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ foo: "bar" }),
    });
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });

    const result2 = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result2.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });
  });

  it("gets same session back (concurrent)", async () => {
    app.get("/concurrent", async (event) => {
      const sessions = await Promise.all(
        [1, 2, 3].map(() =>
          useSession(event, sessionConfig).then((s) => ({
            id: s.id,
            data: s.data,
          })),
        ),
      );
      return {
        sessions,
      };
    });
    const result = await t.fetch("/concurrent", {
      headers: { Cookie: cookie },
    });
    expect(await result.json()).toMatchObject({
      sessions: [1, 2, 3].map(() => ({ id: "1", data: { foo: "bar" } })),
    });
  });

  it("clearSession sets maxAge=0 to delete cookie", async () => {
    t.app.get("/clear", async (event) => {
      await clearSession(event, sessionConfig);
      return { cleared: true };
    });
    const res = await t.fetch("/clear", {
      headers: { Cookie: cookie },
    });
    const cookies = res.headers.getSetCookie();
    expect(cookies.length).toBeGreaterThanOrEqual(1);
    expect(cookies[0]).toContain("Max-Age=0");
  });

  it("unseals and reseals legacy sessions sealed with iterations: 1", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    const result = await t.fetch("/", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    expect(await result.json()).toMatchObject({
      session: { id: "legacy", data: { foo: "legacy" } },
    });

    // Legacy cookie is transparently resealed with the current default
    const setCookies = result.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    const resealed = decodeURIComponent(setCookies[0].match(/h3-test=([^;]+)/)![1]);
    expect(
      await unseal(resealed, sessionConfig.password, sealDefaults), // current iterations, no fallback
    ).toMatchObject({ id: "legacy", data: { foo: "legacy" } });
  });

  it("rejects legacy sessions with legacySealFallback: false", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    t.app.all("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        legacySealFallback: false,
      });
      return { session };
    });

    const result = await t.fetch("/strict", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    const body = await result.json();
    expect(body.session.id).not.toBe("legacy");
    expect(body.session.data).toEqual({});
  });

  describeMatrix("session password list", (ctx, { it, expect }) => {
    const newPassword = "senha-nova-rotacao-0123456789abcdefgh";
    const oldPassword = "senha-antiga-rotacao-0123456789abcdef";
    const removedPassword = "senha-removida-0123456789abcdefghijk";
    const rotating: SessionConfig = {
      name: "h3-rotate",
      password: [newPassword, oldPassword],
      generateId: () => "rotate-new",
    };
    const payload = { id: "old-1", createdAt: Date.now(), data: { user: "alice" } };
    const legacyOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };
    const sessionCookie = (res: Response) =>
      decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-rotate=([^;]+)/)![1]);

    beforeEach(() => {
      ctx.app.get("/create", async (event) => {
        const session = await updateSession(event, rotating, { user: "alice" });
        return { id: session.id };
      });
      ctx.app.get("/read", async (event) => {
        const session = await getSession(event, rotating);
        return { id: session.id, data: session.data };
      });
      ctx.app.get("/write", async (event) => {
        const session = await updateSession(event, rotating, { user: "bob" });
        return { id: session.id, data: session.data };
      });
      ctx.app.get("/idle", async (event) => {
        const session = await getSession(event, { ...rotating, idleTimeout: 60 });
        return { id: session.id, data: session.data };
      });
    });

    it("seals new sessions with the first password only", async () => {
      const res = await ctx.fetch("/create");
      const sealed = sessionCookie(res);
      expect(await unseal(sealed, newPassword, sealDefaults)).toMatchObject({ id: "rotate-new" });
      await expect(unseal(sealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("reads a session sealed with an older password without creating a new one", async () => {
      const sealed = await seal(payload, oldPassword, sealDefaults);
      const res = await ctx.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old-1", data: { user: "alice" } });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("unseals legacy sessions with an older password and reseals them with the first", async () => {
      const sealed = await seal(payload, oldPassword, legacyOptions);
      const res = await ctx.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old-1", data: { user: "alice" } });

      const resealed = sessionCookie(res);
      expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({ id: "old-1" });
      await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("treats a session sealed with a password removed from the list as missing", async () => {
      const sealed = await seal(payload, removedPassword, sealDefaults);
      const res = await ctx.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
      const body = await res.json();
      expect(body.id).not.toBe("old-1");
      expect(body.data).toEqual({});
    });

    it("reseals with the first password when a write happens", async () => {
      const sealed = await seal(payload, oldPassword, sealDefaults);
      const res = await ctx.fetch("/write", { headers: { Cookie: `h3-rotate=${sealed}` } });

      const resealed = sessionCookie(res);
      expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({
        id: "old-1",
        data: { user: "bob" },
      });
      await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("reseals with the first password when idleTimeout slides the window", async () => {
      const sealed = await seal(
        { ...payload, lastSeenAt: Date.now() - 45_000 },
        oldPassword,
        sealDefaults,
      );
      const res = await ctx.fetch("/idle", { headers: { Cookie: `h3-rotate=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old-1", data: { user: "alice" } });

      const resealed = sessionCookie(res);
      expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({ id: "old-1" });
      await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("keeps a single string password working", async () => {
      ctx.app.get("/single", async (event) => {
        const session = await updateSession(event, { ...rotating, password: newPassword }, {
          user: "carol",
        });
        return { id: session.id };
      });
      const res = await ctx.fetch("/single");
      const sealed = sessionCookie(res);
      expect(await unseal(sealed, newPassword, sealDefaults)).toMatchObject({
        id: "rotate-new",
        data: { user: "carol" },
      });

      const read = await ctx.fetch("/read", { headers: { Cookie: `h3-rotate=${sealed}` } });
      expect(await read.json()).toMatchObject({ id: "rotate-new", data: { user: "carol" } });
    });

    it("rejects an empty password list in useSession, getSession and sealSession", async () => {
      const empty: SessionConfig = { ...rotating, password: [] };
      ctx.app.get("/empty/use", (event) => useSession(event, empty));
      ctx.app.get("/empty/get", (event) => getSession(event, empty));
      ctx.app.get("/empty/seal", (event) => sealSession(event, empty));

      for (const path of ["/empty/use", "/empty/get", "/empty/seal"]) {
        const res = await ctx.fetch(path);
        expect(res.status).toBe(500);
      }
      const message = "At least one session password is required";
      expect(ctx.errors.map((error) => error.message)).toEqual([message, message, message]);
      ctx.errors = [];
    });

    it("reports an empty password entry and a short one instead of skipping them", async () => {
      ctx.app.get("/empty-entry", (event) =>
        getSession(event, { ...rotating, password: [newPassword, ""] }),
      );
      ctx.app.get("/short-entry", (event) =>
        getSession(event, { ...rotating, password: [newPassword, "curta", oldPassword] }),
      );
      const sealed = await seal(payload, oldPassword, sealDefaults);

      await ctx.fetch("/empty-entry", { headers: { Cookie: `h3-rotate=${sealed}` } });
      await ctx.fetch("/short-entry", { headers: { Cookie: `h3-rotate=${sealed}` } });
      expect(ctx.errors.map((error) => error.message)).toEqual([
        "Session password must not be empty",
        "Session password too short (min 32 characters required)",
      ]);
      ctx.errors = [];
    });

    it("reads sessions with a duplicated password list as with a unique one", async () => {
      ctx.app.get("/dup", (event) =>
        getSession(event, { ...rotating, password: [newPassword, newPassword, oldPassword] }),
      );
      const sealed = await seal(payload, oldPassword, sealDefaults);
      const res = await ctx.fetch("/dup", { headers: { Cookie: `h3-rotate=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old-1", data: { user: "alice" } });
    });

    it("keeps an expired session expired with a password list", async () => {
      const sealed = await seal(payload, oldPassword, { ...sealDefaults, ttl: -120_000 });
      ctx.app.get("/expired", (event) => unsealSession(event, rotating, sealed));
      await ctx.fetch("/expired");
      expect(ctx.errors.map((error) => error.message)).toEqual(["Expired seal"]);
      ctx.errors = [];
    });
  });

  it("idleTimeout slides expiration for active sessions", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idle",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `idle-${++idCtr}`,
      };
      t.app.get("/idle", async (event) => {
        const session = await useSession(event, config);
        await session.update((data) => ({ hits: (data.hits || 0) + 1 }));
        return { id: session.id, data: session.data };
      });
      const idleCookie = (res: Response) =>
        res.headers.getSetCookie().find((c) => c.startsWith("h3-idle="));

      // t=0: new session
      const res1 = await t.fetch("/idle");
      expect((await res1.json()).id).toBe("idle-1");
      let cookie = idleCookie(res1)!;

      // t=45s: active request keeps the session and slides the cookie expiry
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/idle", { headers: { Cookie: cookie } });
      expect(await res2.json()).toMatchObject({ id: "idle-1", data: { hits: 2 } });
      const resealed = idleCookie(res2);
      expect(resealed).toBeDefined();
      expect(resealed).toContain(`Expires=${new Date(t0 + 45_000 + 60_000).toUTCString()}`);
      cookie = resealed!;

      // t=90s: past createdAt + idleTimeout, but only 45s idle — the session and
      // its data survive the reseals
      vi.setSystemTime(t0 + 90_000);
      const res3 = await t.fetch("/idle", { headers: { Cookie: cookie } });
      expect(await res3.json()).toMatchObject({ id: "idle-1", data: { hits: 3 } });
    } finally {
      vi.useRealTimers();
    }
  });

  it("idleTimeout expires sessions after exactly idleTimeout of inactivity", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idle-exp",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `exp-${++idCtr}`,
      };
      t.app.get("/idle-expiry", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });

      const res1 = await t.fetch("/idle-expiry");
      expect((await res1.json()).id).toBe("exp-1");
      const cookie = res1.headers.getSetCookie().find((c) => c.startsWith("h3-idle-exp="))!;

      // No clock-skew slack: still alive at 59s of inactivity
      vi.setSystemTime(t0 + 59_000);
      const res2 = await t.fetch("/idle-expiry", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("exp-1");

      // ...and reset at 61s, measured from the original cookie's reseal time
      vi.setSystemTime(t0 + 61_000);
      const res3 = await t.fetch("/idle-expiry", { headers: { Cookie: cookie } });
      expect((await res3.json()).id).toBe("exp-2");
    } finally {
      vi.useRealTimers();
    }
  });

  it("maxAge caps a sliding session", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-both",
        password: sessionConfig.password,
        maxAge: 120,
        idleTimeout: 60,
        generateId: () => `both-${++idCtr}`,
      };
      t.app.get("/both", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });
      const bothCookie = (res: Response) =>
        res.headers.getSetCookie().find((c) => c.startsWith("h3-both="))!;

      const res1 = await t.fetch("/both");
      expect((await res1.json()).id).toBe("both-1");
      let cookie = bothCookie(res1);

      // t=45s: idle window (t+60s) runs out before the absolute cap (t0+120s)
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("both-1");
      cookie = bothCookie(res2);
      expect(cookie).toContain(`Expires=${new Date(t0 + 105_000).toUTCString()}`);

      // t=90s: now the absolute cap is the earlier of the two, so it wins
      vi.setSystemTime(t0 + 90_000);
      const res3 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res3.json()).id).toBe("both-1");
      cookie = bothCookie(res3);
      expect(cookie).toContain(`Expires=${new Date(t0 + 120_000).toUTCString()}`);

      // t=121s: only 31s idle, but past createdAt + maxAge — session resets
      vi.setSystemTime(t0 + 121_000);
      const res4 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res4.json()).id).toBe("both-2");
    } finally {
      vi.useRealTimers();
    }
  });

