    it("reseals with the first password when a write happens", async () => {
      const sealed = await seal(payload, oldPassword, sealDefaults);
      const res = await t.fetch("/write", { headers: { Cookie: `h3-rotate=${sealed}` } });

      const resealed = sessionCookie(res);
      expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({
        id: "old-1",
        data: { user: "bob" },
